const tabId = 2017692062;
const iframeTree = await browserjs(tabId, () => {
  function getFrames(win, depth = 0) {
    const frames = [];
    for (let i = 0; i < win.frames.length; i++) {
      try {
        const f = win.frames[i];
        frames.push({
          depth,
          index: i,
          src: f.location.href,
          hasCKEDITOR: !!f.CKEDITOR,
          title: f.document.title
        });
        frames.push(...getFrames(f, depth + 1));
      } catch (e) {
        frames.push({ depth, index: i, error: e.message });
      }
    }
    return frames;
  }
  return getFrames(window);
});
console.log("Iframe tree:", JSON.stringify(iframeTree, null, 2));

